import threading


class SafeCounter:
    def __init__(self, initial: int = 0):
        self._lock = threading.Lock()
        self._value = initial

    def _validate_count(self, n):
        if isinstance(n, bool) or not isinstance(n, int):
            raise ValueError("count must be a non-bool integer")
        if n < 0:
            raise ValueError("count must be >= 0")

    def increment(self, n: int = 1) -> None:
        if isinstance(n, bool) or not isinstance(n, int):
            raise ValueError("count must be a non-bool integer")
        with self._lock:
            self._value += n

    def decrement(self, n: int = 1) -> None:
        if isinstance(n, bool) or not isinstance(n, int):
            raise ValueError("count must be a non-bool integer")
        with self._lock:
            self._value -= n

    def value(self) -> int:
        with self._lock:
            return self._value

    def compare_and_set(self, expected: int, new: int) -> bool:
        if isinstance(expected, bool) or not isinstance(expected, int):
            raise ValueError("expected must be a non-bool integer")
        if isinstance(new, bool) or not isinstance(new, int):
            raise ValueError("new must be a non-bool integer")
        with self._lock:
            if self._value == expected:
                self._value = new
                return True
            return False

    def transfer_to(self, other: "SafeCounter", n: int) -> None:
        self._validate_count(n)
        if other is self:
            return
        if not isinstance(other, SafeCounter):
            raise ValueError("other must be a SafeCounter")
        first, second = (self, other) if id(self) < id(other) else (other, self)
        with first._lock:
            with second._lock:
                self._value -= n
                other._value += n
